function registerRemoteAccessApi(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    HTTP.register!(router, "GET", path_prefix * "/computer/api/json", OpenAPI.Servers.middleware(impl, get_computer_read, get_computer_validate, get_computer_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/api/json", OpenAPI.Servers.middleware(impl, get_jenkins_read, get_jenkins_validate, get_jenkins_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/job/{name}/api/json", OpenAPI.Servers.middleware(impl, get_job_read, get_job_validate, get_job_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/job/{name}/config.xml", OpenAPI.Servers.middleware(impl, get_job_config_read, get_job_config_validate, get_job_config_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/job/{name}/lastBuild/api/json", OpenAPI.Servers.middleware(impl, get_job_last_build_read, get_job_last_build_validate, get_job_last_build_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/job/{name}/{number}/logText/progressiveText", OpenAPI.Servers.middleware(impl, get_job_progressive_text_read, get_job_progressive_text_validate, get_job_progressive_text_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/queue/api/json", OpenAPI.Servers.middleware(impl, get_queue_read, get_queue_validate, get_queue_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/queue/item/{number}/api/json", OpenAPI.Servers.middleware(impl, get_queue_item_read, get_queue_item_validate, get_queue_item_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/view/{name}/api/json", OpenAPI.Servers.middleware(impl, get_view_read, get_view_validate, get_view_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/view/{name}/config.xml", OpenAPI.Servers.middleware(impl, get_view_config_read, get_view_config_validate, get_view_config_invoke; optional_middlewares...))
    HTTP.register!(router, "HEAD", path_prefix * "/api/json", OpenAPI.Servers.middleware(impl, head_jenkins_read, head_jenkins_validate, head_jenkins_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/createItem", OpenAPI.Servers.middleware(impl, post_create_item_read, post_create_item_validate, post_create_item_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/createView", OpenAPI.Servers.middleware(impl, post_create_view_read, post_create_view_validate, post_create_view_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/job/{name}/build", OpenAPI.Servers.middleware(impl, post_job_build_read, post_job_build_validate, post_job_build_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/job/{name}/config.xml", OpenAPI.Servers.middleware(impl, post_job_config_read, post_job_config_validate, post_job_config_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/job/{name}/doDelete", OpenAPI.Servers.middleware(impl, post_job_delete_read, post_job_delete_validate, post_job_delete_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/job/{name}/disable", OpenAPI.Servers.middleware(impl, post_job_disable_read, post_job_disable_validate, post_job_disable_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/job/{name}/enable", OpenAPI.Servers.middleware(impl, post_job_enable_read, post_job_enable_validate, post_job_enable_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/job/{name}/lastBuild/stop", OpenAPI.Servers.middleware(impl, post_job_last_build_stop_read, post_job_last_build_stop_validate, post_job_last_build_stop_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/view/{name}/config.xml", OpenAPI.Servers.middleware(impl, post_view_config_read, post_view_config_validate, post_view_config_invoke; optional_middlewares...))
    return router
end
